#include <iostream>
#include <mutex>
#include <thread>

long long balance = 0;
std::mutex m;

void deposit(int n) {
    for (int i = 0; i < n; ++i) {
        std::lock_guard<std::mutex> g(m);   // acquires at construction...
        balance += 100;                     // critical section
    }                                       // ...releases at scope exit, even on throw
}

int main() {
    std::thread a(deposit, 1000), b(deposit, 1000);
    a.join();
    b.join();
    std::cout << balance << '\n';           // 200000, every run
    return 0;
}

#include <condition_variable>
#include <iostream>
#include <mutex>
#include <queue>
#include <thread>

std::queue<int> q;
std::mutex m;
std::condition_variable cv;

void consumer() {
    for (int got = 0; got < 5; ) {
        std::unique_lock<std::mutex> lk(m);
        while (q.empty()) cv.wait(lk);   // 'if' would break on spurious wakeups
        std::cout << q.front() << '\n';
        q.pop();
        ++got;
    }
}

int main() {
    std::thread c(consumer);
    for (int i = 1; i <= 5; ++i) {
        {   std::lock_guard<std::mutex> lk(m);
            q.push(i);
        }
        cv.notify_one();                 // notify AFTER releasing is fine and common
    }
    c.join();
    return 0;
}

#include <mutex>

struct Account { std::mutex m; long long cents = 0; };

// BAD: transfer(a,b) locks a then b; transfer(b,a) locks b then a. Under
// concurrent opposite-direction transfers the two threads can deadlock.
void transfer_bad(Account& a, Account& b, long long c) {
    std::lock_guard<std::mutex> la(a.m);
    std::lock_guard<std::mutex> lb(b.m);
    a.cents -= c;
    b.cents += c;
}

// GOOD (C++17): one call acquires both mutexes deadlock-free.
void transfer_ok(Account& a, Account& b, long long c) {
    std::scoped_lock both(a.m, b.m);
    a.cents -= c;
    b.cents += c;
}

